#include <iostream>
using namespace std;

void countDown(int n) {
    if (n == 0) {
        cout << "{stop}" << endl;
        return;
    }
    cout << "往下 " << n << endl;
    countDown(n - 1);
}

int main() {
    int n = 0;
    cin >> n;

    countDown(n);
    return 0;
}
